mapper.select:
select 
from oa_sign_file_cleanup
where (
        status in ('PENDING', 'RETRY')
        and (next_retry_time is null or next_retry_time <= #{dueTime})
      )
   or (
        status = 'PROCESSING'
        and lease_expires_time <= #{dueTime}
      )
order by coalesce(next_retry_time, created_time), cleanup_id
limit #{limit}

mapper.update:
update oa_sign_file_cleanup
set status = 'PROCESSING',
    processing_token = #{processingToken},
    lease_expires_time = #{leaseExpiresTime},
    version = version + 1,
    updated_time = sysdate()
where cleanup_id = #{cleanupId}
  and version = #{version}
  and (
        (
            status in ('PENDING', 'RETRY')
            and (next_retry_time is null or next_retry_time <= #{dueTime})
        )
        or (
            status = 'PROCESSING'
            and lease_expires_time <= #{dueTime}
        )
      )
